import{D as e}from"./index-BbvXgB4H.js";var t=`docs/references/hsk/sources/hsk2.pdf`,n=(e,n)=>`${t}#printed-pages=${e}&pdf-pages=${n}`,r=n(`102-111`,`116-125`),i=t=>({image:e(`/assets/group3/lesson-hsk2-l12-${t}-v1.webp`),imageSrcSet:`${e(`/assets/group3/lesson-hsk2-l12-${t}-720w-v1.webp`)} 720w, ${e(`/assets/group3/lesson-hsk2-l12-${t}-v1.webp`)} 1400w`}),a={wang:{hanzi:`王一雪`,pinyin:`Wáng Yīxuě`,nameTh:`หวังอี้เสวี่ย`,nameEn:`Wang Yixue`,...i(`weather-call`),imageFocus:`30% center`},bai:{hanzi:`白家月`,pinyin:`Bái Jiāyuè`,nameTh:`ไป๋เจียเยว่`,nameEn:`Bai Jiayue`,...i(`weather-call`),imageFocus:`68% center`},yifei:{hanzi:`王一飞`,pinyin:`Wáng Yīfēi`,nameTh:`หวังอี้เฟย`,nameEn:`Wang Yifei`,...i(`snow-call`),imageFocus:`68% center`},liWen:{hanzi:`李文`,pinyin:`Lǐ Wén`,nameTh:`หลี่เหวิน`,nameEn:`Li Wen`,...i(`running`),imageFocus:`30% center`}},o=[[1,`事情`,`shìqing`,`n.`,`affair; matter`,`เรื่อง / ธุระ`,103,117],[2,`晴`,`qíng`,`adj.`,`sunny`,`ท้องฟ้าแจ่มใส`,103,117],[3,`正`,`zhèng`,`adv.`,`right now; in progress`,`กำลัง / พอดี`,103,117],[4,`天气`,`tiānqì`,`n.`,`weather`,`อากาศ`,103,117],[5,`下雪`,`xiàxuě`,`v.`,`snow`,`หิมะตก`,103,117],[6,`外面`,`wàimian`,`n.`,`outside`,`ข้างนอก`,105,119],[7,`阴`,`yīn`,`adj.`,`cloudy`,`ครึ้ม / มีเมฆ`,105,119],[8,`从小`,`cóngxiǎo`,`adv.`,`since childhood`,`ตั้งแต่เด็ก`,107,121],[9,`地铁`,`dìtiě`,`n.`,`subway`,`รถไฟใต้ดิน`,107,121],[10,`楼`,`lóu`,`n.`,`building; floor`,`อาคาร / ชั้น`,107,121],[11,`冷`,`lěng`,`adj.`,`cold`,`หนาว`,103,117],[12,`说话`,`shuōhuà`,`v.`,`talk; speak`,`พูดคุย`,103,117],[13,`有点儿`,`yǒudiǎnr`,`adv.`,`a little; somewhat`,`ค่อนข้าง / นิดหน่อย`,103,117],[14,`网上`,`wǎngshàng`,`n.`,`online`,`ทางออนไลน์`,105,119],[15,`出去`,`chūqu`,`v.`,`go out`,`ออกไป`,105,119],[16,`记得`,`jìde`,`v.`,`remember`,`จำไว้ / จำได้`,105,119],[17,`电话`,`diànhuà`,`n.`,`telephone call`,`โทรศัพท์`,105,119],[18,`慢慢`,`mànmàn`,`adv.`,`slowly`,`ช้า ๆ`,107,121],[19,`等`,`děng`,`v.`,`wait`,`รอ`,107,121],[20,`跑步`,`pǎobù`,`v.`,`run; jog`,`วิ่งออกกำลังกาย`,107,121]].map(([e,t,r,i,a,o,s,c])=>({index:e,hanzi:t,pinyin:r,type:i,en:a,th:o,thAid:o,page:s,translationKind:`editorial-aid`,sourceRef:n(String(s),String(c))})),s=(e,t,n,r,i,a,o,s)=>({role:t,speaker:n,pinyin:r,reading:r,hanzi:i,en:a,th:o,visual:{zh:i,th:o,focus:s},sourceRef:e}),c=n(`103`,`117`),l=n(`105`,`119`),u=n(`107`,`121`),d=[{id:`h2l12-weather-call`,number:`01`,glyph:`晴`,title:`这里比北京冷多了`,titleTh:`ที่นี่หนาวกว่าปักกิ่งมาก`,titleEn:`It is much colder here than in Beijing`,place:`电话中`,placeTh:`ทางโทรศัพท์`,...i(`weather-call`),imageAlt:{th:`หวังอี้เสวี่ยรับโทรศัพท์จากไป๋เจียเยว่`,zh:`王一雪接白家月电话场景`,en:`Wang Yixue taking Bai Jiayue’s call`},source:`Text 1 · หน้าเล่ม 103 · PDF หน้า 117`,sourcePage:`103`,sourceRef:c,context:`白家月给王一雪打电话，两个人谈北京和白家月那里的天气。`,contextTh:`ไป๋เจียเยว่โทรหาหวังอี้เสวี่ย ทั้งสองคุยเรื่องอากาศที่ปักกิ่งและที่อยู่ของไป๋เจียเยว่`,contextEn:`Bai calls Wang and they discuss the weather in Beijing and where Bai is staying.`,characters:[{role:`A`,profile:`wang`,noteTh:`คนที่อยู่ปักกิ่ง`,noteZh:`在北京接电话的人`,noteEn:`The caller in Beijing`},{role:`B`,profile:`bai`,noteTh:`คนที่อยู่ในพื้นที่หิมะตก`,noteZh:`在下雪地区的学生`,noteEn:`The student where it is snowing`}],lines:[s(c,`A`,`王一雪`,`Wéi, Jiāyuè, shì nǐ a! Yǒu shénme shìqing ma?`,`喂，家月，是你啊！有什么事情吗？`,`Hello, Jiayue, it’s you! Is anything the matter?`,`ฮัลโหล เจียเยว่ เธอนั่นเอง มีธุระอะไรไหม?`,`30% center`),s(c,`B`,`白家月`,`Méi shénme shì, jiù xiǎng gēn nín shuōshuo huà.`,`没什么事，就想跟您说说话。`,`Nothing important; I just wanted to talk with you.`,`ไม่มีธุระอะไร แค่อยากคุยกับคุณ`,`68% center`),s(c,`A`,`王一雪`,`Hǎo a. Nǐ jīntiān méi kè ma?`,`好啊。你今天没课吗？`,`Sure. Don’t you have class today?`,`ได้สิ วันนี้เธอไม่มีเรียนหรือ?`,`30% center`),s(c,`B`,`白家月`,`Xiàwǔ yǒu kè. Nín nàli tiānqì zěnmeyàng?`,`下午有课。您那里天气怎么样？`,`I have class in the afternoon. How is the weather there?`,`มีเรียนตอนบ่าย ที่นั่นอากาศเป็นอย่างไรบ้าง?`,`68% center`),s(c,`A`,`王一雪`,`Běijīng zhè jǐ tiān suīrán shì qíngtiān, dànshì yǒudiǎnr lěng.`,`北京这几天虽然是晴天，但是有点儿冷。`,`Although Beijing has been sunny these days, it is a little cold.`,`ช่วงนี้ปักกิ่งแม้ฟ้าแจ่มใส แต่ค่อนข้างหนาว`,`30% center`),s(c,`B`,`白家月`,`Wǒ zhèlǐ bǐ Běijīng lěng duō le, wàibian hái zhèng xiàzhe xuě ne!`,`我这里比北京冷多了，外边还正下着雪呢！`,`It is much colder here than in Beijing, and it is snowing outside right now!`,`ที่นี่หนาวกว่าปักกิ่งมาก ข้างนอกกำลังมีหิมะตกอยู่เลย!`,`68% center`)],qte:{after:4,prompt:{th:`อากาศที่ไป๋เจียเยว่อยู่เป็นอย่างไร?`,zh:`白家月那里的天气怎么样？`,en:`What is the weather like where Bai Jiayue is?`},options:[{value:`很冷，正下雪`,zh:`很冷，正下雪`,pinyin:`hěn lěng, zhèng xiàxuě`,th:`หนาวมากและกำลังหิมะตก`},{value:`很热`,zh:`很热`,pinyin:`hěn rè`,th:`ร้อนมาก`},{value:`下雨`,zh:`下雨`,pinyin:`xiàyǔ`,th:`ฝนตก`}],correct:`很冷，正下雪`,evidence:`我这里比北京冷多了，外边还正下着雪呢！`,evidenceTh:`ที่นี่หนาวกว่าปักกิ่งมากและข้างนอกกำลังหิมะตก`,sourceRef:c},builder:{prompt:{th:`เรียงประโยคเปรียบเทียบความหนาว`,zh:`重组带“多了”的比较句`,en:`Rebuild the comparison with 多了`},answer:[`我这里`,`比`,`北京`,`冷`,`多了`],tiles:[`北京`,`多了`,`我这里`,`冷`,`比`],gloss:{我这里:`ที่นี่ของฉัน`,比:`กว่า`,北京:`ปักกิ่ง`,冷:`หนาว`,多了:`มากกว่าเยอะ`},translationTh:`ที่นี่หนาวกว่าปักกิ่งมาก`,translationEn:`It is much colder here than in Beijing.`,evidence:`Text 1 · หน้าเล่ม 103`,sourceRef:c}},{id:`h2l12-snow-call`,number:`02`,glyph:`雪`,title:`昨天比今天下得大`,titleTh:`เมื่อวานหิมะตกหนักกว่าวันนี้`,titleEn:`It snowed harder yesterday`,place:`电话中`,placeTh:`ทางโทรศัพท์`,...i(`snow-call`),imageAlt:{th:`หวังอี้เสวี่ยโทรถามหวังอี้เฟยเรื่องหิมะ`,zh:`姐妹谈下雪场景`,en:`Sisters discussing snowfall by phone`},source:`Text 2 · หน้าเล่ม 105 · PDF หน้า 119`,sourcePage:`105`,sourceRef:l,context:`王一雪打电话问王一飞下雪的情况，并提醒她少出去。`,contextTh:`หวังอี้เสวี่ยโทรถามหวังอี้เฟยเรื่องหิมะและเตือนให้ออกไปข้างนอกให้น้อยลง`,contextEn:`Wang Yixue calls Wang Yifei about the snow and reminds her to go out less.`,characters:[{role:`A`,profile:`wang`,noteTh:`พี่สาวที่เป็นห่วงอากาศ`,noteZh:`关心天气的姐姐`,noteEn:`The older sister concerned about the weather`},{role:`B`,profile:`teacherWang`,noteTh:`น้องสาวที่สอนออนไลน์`,noteZh:`在网上上课的妹妹`,noteEn:`The younger sister teaching online`}],lines:[s(l,`A`,`王一雪`,`Wéi, Yīfēi, tīng Jiāyuè shuō nǐ nàbian xiàxuě le, xià de dà bu dà?`,`喂，一飞，听家月说你那边下雪了，下得大不大？`,`Hello, Yifei. Jiayue said it snowed there. Was it heavy?`,`ฮัลโหล อี้เฟย ได้ยินเจียเยว่บอกว่าที่นั่นหิมะตก ตกหนักไหม?`,`30% center`),s(l,`B`,`王一飞`,`Jīntiān bú dà, zuótiān bǐ jīntiān xià de dà.`,`今天不大，昨天比今天下得大。`,`Not heavy today; it snowed harder yesterday.`,`วันนี้ไม่หนัก เมื่อวานตกหนักกว่าวันนี้`,`68% center`),s(l,`A`,`王一雪`,`Tiānqì bù hǎo, nǐ qù wàimian de shíhou duō chuān diǎnr yīfu.`,`天气不好，你去外面的时候多穿点儿衣服。`,`The weather is bad. Wear more clothes when you go outside.`,`อากาศไม่ดี เวลาออกไปข้างนอกใส่เสื้อผ้าเพิ่มหน่อย`,`30% center`),s(l,`B`,`王一飞`,`Zhè jǐ tiān wǒ zài wǎngshàng shàngkè, méi chūquguo.`,`这几天我在网上上课，没出去过。`,`I have been teaching online these days and have not gone out.`,`ช่วงนี้ฉันสอนออนไลน์ ยังไม่ได้ออกไปข้างนอก`,`68% center`),s(l,`A`,`王一雪`,`Nà jiù hǎo, yǒu shì jìde gěi wǒ dǎ diànhuà.`,`那就好，有事记得给我打电话。`,`That is good. Remember to call me if anything happens.`,`งั้นก็ดี ถ้ามีอะไรจำไว้ว่าโทรหาฉัน`,`30% center`),s(l,`B`,`王一飞`,`Hǎo de. Xiànzài bù xiàxuě le, wǒ chūqu mǎi diǎnr chī de.`,`好的。现在不下雪了，我出去买点儿吃的。`,`Okay. It is not snowing now, so I will go buy some food.`,`ได้ ตอนนี้หิมะไม่ตกแล้ว ฉันจะออกไปซื้อของกินหน่อย`,`68% center`),s(l,`A`,`王一雪`,`Yí cì duō mǎi diǎnr, yīntiān xiàxuě shénme de jiù shǎo chūqu ba.`,`一次多买点儿，阴天下雪什么的就少出去吧。`,`Buy more at once and go out less on cloudy or snowy days.`,`ซื้อให้มากหน่อยในครั้งเดียว วันครึ้มหรือหิมะตกก็ออกไปให้น้อยลง`,`30% center`)],qte:{after:4,prompt:{th:`วันไหนหิมะตกหนักกว่า?`,zh:`哪天下雪下得更大？`,en:`Which day had heavier snow?`},options:[{value:`昨天`,zh:`昨天`,pinyin:`zuótiān`,th:`เมื่อวาน`},{value:`今天`,zh:`今天`,pinyin:`jīntiān`,th:`วันนี้`},{value:`一样大`,zh:`一样大`,pinyin:`yíyàng dà`,th:`หนักเท่ากัน`}],correct:`昨天`,evidence:`昨天比今天下得大。`,evidenceTh:`เมื่อวานตกหนักกว่าวันนี้`,sourceRef:l},builder:{prompt:{th:`เรียงประโยคเปรียบเทียบปริมาณหิมะ`,zh:`重组带状态补语的比较句`,en:`Rebuild the comparison with a complement of state`},answer:[`昨天`,`比`,`今天`,`下`,`得`,`大`],tiles:[`得`,`今天`,`大`,`昨天`,`下`,`比`],gloss:{昨天:`เมื่อวาน`,比:`กว่า`,今天:`วันนี้`,下:`ตก`,得:`คำช่วยบทเสริม`,大:`หนัก`},translationTh:`เมื่อวานหิมะตกหนักกว่าวันนี้`,translationEn:`It snowed harder yesterday than today.`,evidence:`Text 2 · หน้าเล่ม 105`,sourceRef:l}},{id:`h2l12-running`,number:`03`,glyph:`跑`,title:`一起去跑步`,titleTh:`ไปวิ่งด้วยกัน`,titleEn:`Going for a run together`,place:`电话中`,placeTh:`ทางโทรศัพท์`,...i(`running`),imageAlt:{th:`หลี่เหวินกับไป๋เจียเยว่วิ่งกลางแจ้ง`,zh:`李文和白家月跑步场景`,en:`Li Wen and Bai Jiayue running outdoors`},source:`Text 3 · หน้าเล่ม 107 · PDF หน้า 121`,sourcePage:`107`,sourceRef:u,context:`天气晴朗，李文邀请白家月一起跑步，并说会慢慢跑等她。`,contextTh:`อากาศแจ่มใส หลี่เหวินชวนไป๋เจียเยว่ไปวิ่งและบอกว่าจะวิ่งช้า ๆ รอเธอ`,contextEn:`On a sunny day, Li Wen invites Bai for a run and promises to run slowly and wait for her.`,characters:[{role:`A`,profile:`liWen`,noteTh:`เพื่อนที่ชอบวิ่งตั้งแต่เด็ก`,noteZh:`从小爱跑步的朋友`,noteEn:`The friend who has run since childhood`},{role:`B`,profile:`bai`,noteTh:`เพื่อนที่วิ่งช้ากว่า`,noteZh:`跑得比较慢的朋友`,noteEn:`The friend who runs more slowly`}],lines:[s(u,`A`,`李文`,`Wéi, Jiāyuè, jīntiān tiānqì búcuò, wǒmen qù pǎobù ba!`,`喂，家月，今天天气不错，我们去跑步吧！`,`Hello, Jiayue. The weather is nice today. Let’s go running!`,`ฮัลโหล เจียเยว่ วันนี้อากาศดี เราไปวิ่งกันเถอะ!`,`30% center`),s(u,`B`,`白家月`,`Nǐ pǎobù pǎo de bǐ wǒ kuài, wǒmen néng yìqǐ pǎo ma?`,`你跑步跑得比我快，我们能一起跑吗？`,`You run faster than I do. Can we run together?`,`เธอวิ่งเร็วกว่าฉัน เราวิ่งด้วยกันได้หรือ?`,`68% center`),s(u,`A`,`李文`,`Kěyǐ de, wǒ mànmàn pǎo, děngzhe nǐ.`,`可以的，我慢慢跑，等着你。`,`Of course. I will run slowly and wait for you.`,`ได้สิ ฉันจะวิ่งช้า ๆ และรอเธอ`,`30% center`),s(u,`B`,`白家月`,`Hǎo ba. Nǐ zhēn ài pǎobù a!`,`好吧。你真爱跑步啊！`,`Alright. You really love running!`,`ตกลง เธอชอบวิ่งจริง ๆ!`,`68% center`),s(u,`A`,`李文`,`Wǒ cóngxiǎo jiù jīngcháng gēn bàba pǎobù, pǎobù néng ràng rén kuàilè!`,`我从小就经常跟爸爸跑步，跑步能让人快乐！`,`I have often run with my dad since childhood. Running makes people happy!`,`ฉันวิ่งกับพ่อตั้งแต่เด็ก การวิ่งทำให้คนมีความสุข!`,`30% center`),s(u,`B`,`白家月`,`Hǎo, nà wǒ zhǔnbèi yíxià.`,`好，那我准备一下。`,`Okay, I will get ready.`,`ได้ งั้นฉันเตรียมตัวสักหน่อย`,`68% center`),s(u,`A`,`李文`,`Wǒ xiànzài zuò dìtiě qù zhǎo nǐ, yíhuìr lóuxià jiàn.`,`我现在坐地铁去找你，一会儿楼下见。`,`I am taking the subway to meet you. See you downstairs soon.`,`ตอนนี้ฉันนั่งรถไฟใต้ดินไปหาเธอ อีกสักครู่เจอกันข้างล่าง`,`30% center`)],qte:{after:4,prompt:{th:`หลี่เหวินเริ่มวิ่งตั้งแต่เมื่อไร?`,zh:`李文从什么时候开始跑步？`,en:`When did Li Wen start running?`},options:[{value:`从小`,zh:`从小`,pinyin:`cóngxiǎo`,th:`ตั้งแต่เด็ก`},{value:`昨天`,zh:`昨天`,pinyin:`zuótiān`,th:`เมื่อวาน`},{value:`上大学以后`,zh:`上大学以后`,pinyin:`shàng dàxué yǐhòu`,th:`หลังเข้ามหาวิทยาลัย`}],correct:`从小`,evidence:`我从小就经常跟爸爸跑步。`,evidenceTh:`ฉันวิ่งกับพ่อเป็นประจำตั้งแต่เด็ก`,sourceRef:u},builder:{prompt:{th:`เรียงประโยคเปรียบเทียบความเร็วในการวิ่ง`,zh:`重组跑步比较句`,en:`Rebuild the running comparison`},answer:[`你`,`跑步`,`跑`,`得`,`比我`,`快`],tiles:[`比我`,`跑`,`你`,`快`,`得`,`跑步`],gloss:{你:`เธอ`,跑步:`วิ่ง`,跑:`วิ่ง`,得:`คำช่วยบทเสริม`,比我:`กว่าฉัน`,快:`เร็ว`},translationTh:`เธอวิ่งได้เร็วกว่าฉัน`,translationEn:`You run faster than I do.`,evidence:`Text 3 · หน้าเล่ม 107`,sourceRef:u}}],f={id:`hsk2-l12`,slug:`lesson-12`,level:`hsk2`,number:12,featured:!1,sourceRef:r,source:{title:`新HSK教程 2 · New HSK Course 2`,lesson:`Lesson 12 · 这里比北京冷多了`,printedPages:`102–111`,pdfPages:`116–125`,file:`hsk2.pdf`,sourceRef:r},title:{zh:`这里比北京冷多了`,pinyin:`Zhèlǐ bǐ Běijīng lěng duō le`,en:`It’s much colder here than in Beijing`,thAid:`ที่นี่หนาวกว่าปักกิ่งมาก`},summary:{zh:`朋友们打电话谈天气、下雪和跑步，学习三个带“比”的比较结构。`,en:`Friends discuss weather, snow, and running by phone while learning three comparative patterns with 比.`,thAid:`เพื่อน ๆ คุยทางโทรศัพท์เรื่องอากาศ หิมะ และการวิ่ง พร้อมฝึกโครงสร้างเปรียบเทียบด้วย 比 สามรูป`},translationPolicy:{kind:`editorial-aid`,labelTh:`คำแปลไทยเพื่อช่วยเรียน เรียบเรียงจากต้นฉบับ`},objectives:[{zh:`能听懂并谈论天气情况。`,en:`Understand and talk about weather conditions.`,thAid:`เข้าใจและสนทนาเกี่ยวกับสภาพอากาศ`,sourceRef:n(`102`,`116`)},{zh:`能听懂并描述动作状态之间的差别。`,en:`Understand and describe differences between states of actions.`,thAid:`เข้าใจและบรรยายความแตกต่างของลักษณะการกระทำ`,sourceRef:n(`102`,`116`)},{zh:`掌握比较句的用法，能说明事物之间的差别很大。`,en:`Use comparative sentences to express large differences.`,thAid:`ใช้ประโยคเปรียบเทียบเพื่อบอกความแตกต่างที่มาก`,sourceRef:n(`102`,`116`)}],contents:[{number:`00`,title:`目标与热身`,titleTh:`เป้าหมายและการเตรียมบท`,detail:`Objectives · Warm-Up`,pages:`102`,route:`/home/hsk2/lesson-12/preface/`,sourceRef:n(`102`,`116`)},{number:`01`,title:`这里比北京冷多了`,titleTh:`ที่นี่หนาวกว่าปักกิ่งมาก`,detail:`Text 1 · New Words 1–3`,pages:`103–104`,scene:1,sourceRef:n(`103-104`,`117-118`)},{number:`02`,title:`昨天比今天下得大`,titleTh:`เมื่อวานหิมะตกหนักกว่าวันนี้`,detail:`Text 2 · New Words 4–5`,pages:`105–106`,scene:2,sourceRef:n(`105-106`,`119-120`)},{number:`03`,title:`一起去跑步`,titleTh:`ไปวิ่งด้วยกัน`,detail:`Text 3 · New Words 6–8`,pages:`106–108`,scene:3,sourceRef:n(`106-108`,`120-122`)},{number:`04`,title:`日记与综合练习`,titleTh:`บันทึกและแบบฝึกรวม`,detail:`Text 4 · Exercises`,pages:`108–111`,sourceRef:n(`108-111`,`122-125`)}],vocabulary:o,grammarFocus:[{title:`比较句（4）`,titleEn:`Comparative Sentences (4)`,explanationZh:`“多了”或“得多”放在比较句的形容词后，表示差别很大，结构是“A比B+形容词+多了/得多”。`,explanationEn:`多了 or 得多 follows the adjective in a 比 sentence to indicate a large difference.`,thAid:`วาง 多了 หรือ 得多 หลังคำคุณศัพท์ในประโยค 比 เพื่อบอกว่าต่างกันมาก`,examples:[`我这里比北京冷多了。`,`坐飞机比坐火车快得多。`,`红茶比绿茶好喝得多。`],sourceRef:n(`104`,`118`)},{title:`比较句（5）`,titleEn:`Comparative Sentences (5)`,explanationZh:`动词带状态补语时，“比”可以用在动词前，也可以用在状态补语前。`,explanationEn:`When a verb takes a complement of state, 比 may appear before the verb or before the complement phrase.`,thAid:`เมื่อกริยามีบทเสริมบอกสภาพ สามารถวาง 比 หน้ากริยาหรือก่อนวลีบทเสริมได้`,examples:[`昨天比今天下得大。`,`妈妈比我睡得晚。`,`李文跑得比白家月快。`],sourceRef:n(`106`,`120`)},{title:`比较句（6）`,titleEn:`Comparative Sentences (6)`,explanationZh:`动词既带宾语又带状态补语时，可以把宾语提前或重复动词；离合词需要重复动词性语素。`,explanationEn:`With both an object and a complement of state, move the object forward or repeat the verb; repeat the verbal element of a separable verb.`,thAid:`เมื่อกริยามีทั้งกรรมและบทเสริม ให้ย้ายกรรมมาข้างหน้าหรือซ้ำกริยา และคำกริยาแยกส่วนต้องซ้ำส่วนกริยา`,examples:[`你跑步跑得比我快。`,`白家月汉字写得比陈天中好。`,`他踢足球比我踢得好。`],sourceRef:n(`108`,`122`)}],characters:a,scenes:d};export{f as LESSON_HSK2_L12};